import re
p='specs/sk-doc/066-skill-readability-refinement/002-cli-external-orchestration/008-cli-pi/scratch/diff-1.patch'
text=open(p).read().split('diff --git ')
for chunk in text[1:]:
    name=chunk.split('\n',1)[0]
    if not name.endswith('.md'): continue
    adds=[]; rems=[]
    for l in chunk.splitlines():
        if l.startswith('+') and not l.startswith('+++'): adds.append(l[1:])
        elif l.startswith('-') and not l.startswith('---'): rems.append(l[1:])
    # compare sets of removed lines to added lines for moved content
    from collections import Counter
    ca, cr = Counter(adds), Counter(rems)
    only_removed = list((cr-ca).elements())
    only_added = list((ca-cr).elements())
    print('==',name,'removed-only',len(only_removed),'added-only',len(only_added))
    for l in only_removed: print('  -',l[:160])
    for l in only_added: print('  +',l[:160])
